export const KEEPALIVE_PING = 'remora:ping'
export const KEEPALIVE_PONG = 'remora:pong'

/** Progress events are batched at least this far apart; completion and attention go out at once. */
export const PROGRESS_BATCH_MS = 30_000

export interface Actor {
  clientId: string
  clientName: string
}

